# ---------- risultati e statistiche ----------
def rep(tok, game, match, won, place=None, n=3, score=None, riv=None):
    return q("select report_result('%s','%s','%s',%s,%s,%s,%s,%s)" % (tok, game, match, 'true' if won else 'false', place or 'null', n, 'null' if score is None else score,
             "array[%s]::text[]" % ','.join("'%s'" % r for r in (riv or [])) if riv else 'null'))
o, e = rep(D['token'], 'presagio', 'presagio:ABCD:g1', True, 1, 3, 120, ['Eva', 'Selene']); t('risultato registrato', e == '', e)
rep(D['token'], 'presagio', 'presagio:ABCD:g1', False)
rep(D['token'], 'presagio', 'presagio:ABCD:g2', False, 2, 3, 80)
rep(D['token'], 'gattomina', 'gattomina:WXYZ:g3', True, 1, 2)
rep(Ev['token'], 'presagio', 'presagio:ABCD:g1', False, 2, 3, 90)
o, e = rep(D['token'], 'scacchi', 'scacchi:AAAA:g9', True); t('gioco sconosciuto rifiutato', 'sconosciuto' in e, e)
o, e = rep(D['token'], 'presagio', 'x', True); t('partita non valida rifiutata', 'non valida' in e, e)
st = json.loads(q("select my_stats('%s')" % D['token'])[0]); g = {x['game']: x for x in st['games']}
t('stessa partita contata una volta sola', g['presagio']['played'] == 2 and g['presagio']['won'] == 1, st)
t('statistiche per gioco', g['gattomina'] == {'game': 'gattomina', 'played': 1, 'won': 1}, st)
t('ultime partite, dalla più recente', len(st['recent']) == 3 and st['recent'][0]['game'] == 'gattomina' and 'Eva' in st['recent'][-1]['rivals'], st['recent'])
